from typing import List

class Solution:
    def ambiguousCoordinates(self, s: str) -> List[str]:
        def gen_numbers(seg: str) -> List[str]:
            res = []
            n = len(seg)
            # integer form
            if n == 1 or seg[0] != '0':
                res.append(seg)
            # decimal forms: place decimal after position i (1..n-1)
            for i in range(1, n):
                left = seg[:i]
                right = seg[i:]
                # left must be valid integer part: either "0" or not start with '0'
                if not (left == "0" or left[0] != '0'):
                    continue
                # right (fractional) must not end with '0'
                if right[-1] == '0':
                    continue
                res.append(left + "." + right)
            return res

        inner = s[1:-1]
        n = len(inner)
        ans = []
        for i in range(1, n):
            left_seg = inner[:i]
            right_seg = inner[i:]
            left_nums = gen_numbers(left_seg)
            if not left_nums:
                continue
            right_nums = gen_numbers(right_seg)
            if not right_nums:
                continue
            for a in left_nums:
                for b in right_nums:
                    ans.append(f"({a}, {b})")
        return ans

